const body = $input.first().json.body;
let eventType = 'unknown';
let commentText = '';
let commentId = '';
let senderId = '';
let senderUsername = '';
let mediaId = '';
let postbackPayload = '';
let igAccountId = '';

try {
  const entry = body.entry?.[0];
  igAccountId = entry?.id || '';
  const change = entry?.changes?.[0];
  const messaging = entry?.messaging?.[0];

  if (change?.field === 'comments') {
    eventType = 'comment';
    commentText = change.value?.text || '';
    commentId = change.value?.id || '';
    senderId = change.value?.from?.id || '';
    senderUsername = change.value?.from?.username || '';
    mediaId = change.value?.media?.id || '';
    if (senderId === igAccountId) eventType = 'own_comment';
  } else if (messaging?.postback) {
    eventType = 'postback';
    postbackPayload = messaging.postback.payload || '';
    senderId = messaging.sender?.id || '';
  } else if (messaging?.message && !messaging.message.is_echo) {
    eventType = 'dm';
    commentText = messaging.message.text || '';
    senderId = messaging.sender?.id || '';
  }
} catch (e) {}

return [{ json: {
  eventType,
  commentText: commentText.toLowerCase().trim(),
  commentTextRaw: commentText,
  commentId,
  senderId,
  senderUsername,
  mediaId,
  postbackPayload,
  igAccountId
}}];
